<script lang="ts">
  import type{Contour,PathEdge,DesignOperation,DesignSnapshot}from'@schubert/contracts';
  import{parseMillimetres,validateContour,rectangleContour,contourParts,mm,applyOperations,roundContourCorner,contourArcRadius,contourBounds,memorialContour}from'@schubert/geometry';
  import OutlineImportDialog from'./OutlineImportDialog.svelte';
  import OutlinePresetEditor from'./OutlinePresetEditor.svelte';
  import{describeStudioIssue}from'./issues.ts';
  let{snapshot,elementId,contour,planningProjectId='',documents=[],canReview=false,onchange}:{snapshot:DesignSnapshot;elementId:string;contour:Contour;planningProjectId?:string;documents?:any[];canReview?:boolean;onchange:(operations:DesignOperation[])=>void}=$props();
  let cornerRing=$state('0'),cornerIndex=$state('0'),cornerRadius=$state('20'),cornerMode=$state<'round'|'bevel'>('round'),quickOpen=$state(false);
  const quickRings=$derived([contour.outer,...contour.holes]);
  function applyCorner(){error='';try{const ring=Number(cornerRing),index=Number(cornerIndex),value=parseMillimetres(cornerRadius);if(!value||Number(value)<=0)throw Error('Einen positiven Radius oder eine positive Fasenlänge in mm eingeben.');const edge=quickRings[ring]?.[index],next=edge?.kind==='circular_arc'?contourArcRadius(contour,ring,index,value):roundContourCorner(contour,ring,index,value,cornerMode);const ops:DesignOperation[]=[{type:'set_contour',elementId,contour:next}];applyOperations(snapshot,ops);onchange(ops);}catch(problem){error=(problem as Error).message;}}
  let editing=$state(false),draft:Contour=$state({outer:[],holes:[]}),error=$state(''),holeWidth=$state(''),holeDepth=$state(''),holeX=$state(''),holeY=$state(''),importOpen=$state(false),sourceChanged=$state(false),reviewOpen=$state(false),reviewEvidence=$state(''),acceptedError=$state(''),statement=$state('');
  const provenance=$derived(contour.importProvenance),sourceDocument=$derived(documents.find(d=>(d.version_id??d.id)===provenance?.sourceDocumentVersionId));
  function clearProvenance(){if(draft.importProvenance){delete draft.importProvenance;sourceChanged=true;}}
  function open(){draft=structuredClone($state.snapshot(contour));editing=true;error='';sourceChanged=false;}
  function change(ring:PathEdge[],index:number,axis:'xMm'|'yMm',value:string){const n=parseMillimetres(value);if(n===null){error='Konturkoordinaten bitte eindeutig in mm eingeben.';return;}error='';clearProvenance();ring[index].to={...ring[index].to,[axis]:n};ring[(index+1)%ring.length].from={...ring[index].to};}
  function edgeType(ring:PathEdge[],index:number,value:string){clearProvenance();const e=ring[index];ring[index]=value==='line'?{kind:'line',from:e.from,to:e.to}:{kind:'circular_arc',from:e.from,to:e.to,center:{xMm:e.from.xMm,yMm:e.to.yMm},clockwise:false};}
  function center(ring:PathEdge[],index:number,axis:'xMm'|'yMm',value:string){const n=parseMillimetres(value),e=ring[index];if(n===null||e.kind!=='circular_arc'){error='Kreismittelpunkt bitte in mm angeben.';return;}clearProvenance();e.center={...e.center,[axis]:n};}
  function split(ring:PathEdge[],index:number){const e=ring[index];if(e.kind!=='line'){error='Bögen über ihre echten End- und Mittelpunkte bearbeiten.';return;}clearProvenance();const p={xMm:mm((Number(e.from.xMm)+Number(e.to.xMm))/2),yMm:mm((Number(e.from.yMm)+Number(e.to.yMm))/2)};ring.splice(index,1,{kind:'line',from:{...e.from},to:{...p}},{kind:'line',from:{...p},to:{...e.to}});}
  function remove(ring:PathEdge[],index:number){if(ring.length<=3){error='Ein Polygon benötigt mindestens drei Kanten.';return;}clearProvenance();const next=ring[(index+1)%ring.length];next.from={...ring[index].from};ring.splice(index,1);}
  function addHole(){const w=parseMillimetres(holeWidth),d=parseMillimetres(holeDepth),x=parseMillimetres(holeX),y=parseMillimetres(holeY);if(w===null||d===null||x===null||y===null||Number(w)<=0||Number(d)<=0){error='Ausschnittbreite, Tiefe und Lage in mm vollständig eingeben.';return;}const hole=rectangleContour(w,d).outer.map(e=>({...e,from:{xMm:mm(Number(e.from.xMm)+Number(x)),yMm:mm(Number(e.from.yMm)+Number(y))},to:{xMm:mm(Number(e.to.xMm)+Number(x)),yMm:mm(Number(e.to.yMm)+Number(y))}}));clearProvenance();draft.holes.push(hole);error='';}
  function save(event:SubmitEvent){event.preventDefault();error='';try{const issues=validateContour(draft);if(issues.length)throw Error(issues.join('\n'));const operations:DesignOperation[]=[{type:'set_contour',elementId,contour:draft}];applyOperations(snapshot,operations);onchange(operations);editing=false;}catch(problem){error=describeStudioIssue(snapshot,(problem as Error).message).message;}}
  function applyImport(contour:Contour){const operations:DesignOperation[]=[{type:'set_contour',elementId,contour}];try{applyOperations(snapshot,operations);}catch(problem){throw Error(describeStudioIssue(snapshot,(problem as Error).message).message);}onchange(operations);editing=false;}
  function confirmImport(event:SubmitEvent){event.preventDefault();const value=parseMillimetres(acceptedError);if(!value||!provenance||Number(value)<Number(provenance.curveErrorBoundMm)){error='Mindestens die dokumentierte Importfehlergrenze ausdrücklich akzeptieren.';return;}onchange([{type:'confirm_contour_import',elementId,evidenceVersionId:reviewEvidence,acceptedErrorMm:value,statement}]);reviewOpen=false;error='';}
</script>
{#if ['stone_piece','surface'].includes(snapshot.elements.find(e=>e.id===elementId)?.kind??'')}<OutlinePresetEditor {elementId} {contour} {onchange}/>{/if}
<details class="quick-corners" bind:open={quickOpen}><summary>Ecken runden und Radien einstellen</summary><p>Eine Ecke oder einen bestehenden Bogen wählen. Andere Kanten bleiben unverändert. Alle Angaben in mm.</p><div class="pair"><label>Kontur<select bind:value={cornerRing} onchange={()=>cornerIndex='0'}><option value="0">Außenkontur</option>{#each contour.holes as hole,index}<option value={String(index+1)}>Ausschnitt {index+1}</option>{/each}</select></label><label>Ecke / Kreisbogen<select bind:value={cornerIndex}>{#each quickRings[Number(cornerRing)]??[] as edge,index}<option value={String(index)}>{edge.kind==='circular_arc'?'Bogen':'Ecke'} {index+1} · {edge.from.xMm} / {edge.from.yMm}</option>{/each}</select></label></div><div class="pair"><label>Bearbeitung<select bind:value={cornerMode} disabled={quickRings[Number(cornerRing)]?.[Number(cornerIndex)]?.kind==='circular_arc'}><option value="round">Rundung</option><option value="bevel">Fase</option></select></label><label>{cornerMode==='bevel'&&quickRings[Number(cornerRing)]?.[Number(cornerIndex)]?.kind!=='circular_arc'?'Fasenlänge':'Radius'} (mm)<input inputmode="decimal" bind:value={cornerRadius}/></label></div><button type="button" class="btn small primary" onclick={applyCorner}>Geometrie anpassen</button></details><div class="contour-actions"><button class="btn small" onclick={()=>importOpen=true}>SVG / DXF importieren</button>{#if !editing}<button class="btn small" onclick={open}>Kontur & Bögen bearbeiten</button>{/if}</div>
{#if provenance}<div class="import-provenance"><strong>{provenance.format.toUpperCase()} · {provenance.approximated?'Kontrollierte Kurvennäherung':'Analytische Kontur'}</strong><p>{contourParts(contour).length} Bestandteile · höchstens {provenance.curveErrorBoundMm} mm Importfehler · {provenance.review?'fachlich bestätigt':'Fachprüfung offen'}</p>{#if sourceDocument}<a data-sveltekit-reload target="_blank" rel="noreferrer" href={`/api/v1/documents/${sourceDocument.document_id}/download?version=${provenance.sourceDocumentVersionId}&inline=1`}>Unveränderte Originalversion öffnen</a>{/if}<details><summary>Quellennachweis</summary><p class="hash">SHA-256 {provenance.sourceContentHash}</p><p>{provenance.parserVersion} · bestätigte Einheit {provenance.sourceUnit} · Quantisierung 0,01 mm</p></details>{#if canReview&&!provenance.review}<button class="btn small" onclick={()=>reviewOpen=!reviewOpen}>Kontur und Fehlergrenze fachlich prüfen</button>{/if}</div>{/if}
{#if reviewOpen&&provenance}<form class="contour-editor" onsubmit={confirmImport}><p>Bestätigen Sie die konkrete Originalableitung und ihre Eignung für den beschriebenen Zweck. Nutzungsrechte und spätere Fertigungsfreigaben bleiben getrennte Nachweise.</p><label>Eigenes Kontur-/Toleranz-Prüfprotokoll<select bind:value={reviewEvidence} required><option value="">Versionierten Nachweis auswählen</option>{#each documents.filter(d=>(d.version_id??d.id)!==provenance?.sourceDocumentVersionId) as doc}<option value={doc.version_id??doc.id}>{doc.name}</option>{/each}</select></label><label>Akzeptierter Importfehler (mm)<input bind:value={acceptedError} inputmode="decimal" required/></label><label>Geprüfter Zweck und konkrete Erklärung<textarea bind:value={statement} minlength="10" required rows="4"></textarea></label><button class="btn small primary" type="submit">Fachprüfung revisionsgebunden speichern</button></form>{/if}
{#if !editing&&error}<p class="error" role="alert">{error}</p>{/if}
{#if editing}<form class="contour-editor" onsubmit={save}><p>Lokale Koordinaten in mm. Benachbarte Endpunkte bleiben verbunden. Kreisbögen behalten ihren echten Mittelpunkt.</p>{#if sourceChanged}<p class="error">Manuell geänderte Kontur: Die unveränderte Originalableitung und ihre frühere Fachbestätigung gelten für diesen Entwurf nicht mehr.</p>{/if}
  {#each contourParts(draft) as part,partIndex}<div class="contour-part">{#if partIndex}<header><strong>Bestandteil {partIndex+1}</strong><button type="button" onclick={()=>{clearProvenance();draft.islands?.splice(partIndex-1,1);}}>Bestandteil entfernen</button></header>{/if}{#each [part.outer,...part.holes] as ring,ringIndex}<section><header><strong>{ringIndex?'Ausschnitt '+ringIndex:'Außenkontur'}</strong>{#if ringIndex}<button type="button" onclick={()=>{clearProvenance();part.holes.splice(ringIndex-1,1);}}>Ausschnitt entfernen</button>{/if}</header>
    {#each ring as edge,index}<div class="edge"><span>Kante {index+1} · von {edge.from.xMm} / {edge.from.yMm}</span><label>Kantentyp<select value={edge.kind} onchange={(e)=>edgeType(ring,index,e.currentTarget.value)}><option value="line">Gerade</option><option value="circular_arc">Kreisbogen</option></select></label><div class="pair"><label>Endpunkt X<input inputmode="decimal" value={edge.to.xMm} onchange={(e)=>change(ring,index,'xMm',e.currentTarget.value)}/></label><label>Endpunkt Y<input inputmode="decimal" value={edge.to.yMm} onchange={(e)=>change(ring,index,'yMm',e.currentTarget.value)}/></label></div>
      {#if edge.kind==='circular_arc'}<div class="pair"><label>Mittelpunkt X<input inputmode="decimal" value={edge.center.xMm} onchange={(e)=>center(ring,index,'xMm',e.currentTarget.value)}/></label><label>Mittelpunkt Y<input inputmode="decimal" value={edge.center.yMm} onchange={(e)=>center(ring,index,'yMm',e.currentTarget.value)}/></label></div><label class="direction"><input type="checkbox" bind:checked={edge.clockwise} onchange={clearProvenance}/>Im Uhrzeigersinn</label>{/if}
      <div class="edge-actions"><button type="button" onclick={()=>split(ring,index)}>Teilen</button><button type="button" onclick={()=>remove(ring,index)}>Entfernen</button></div></div>{/each}</section>{/each}</div>{/each}
  <details><summary>Geschlossenen Ausschnitt hinzufügen</summary><div class="pair"><label>Breite<input bind:value={holeWidth} inputmode="decimal"/></label><label>Tiefe<input bind:value={holeDepth} inputmode="decimal"/></label><label>Position X<input bind:value={holeX} inputmode="decimal"/></label><label>Position Y<input bind:value={holeY} inputmode="decimal"/></label></div><button type="button" class="btn small" onclick={addHole}>Ausschnitt ergänzen</button></details>
  {#if error}<p class="error" role="alert">{error}</p>{/if}<div class="actions"><button class="btn small" type="button" onclick={()=>{editing=false;error='';}}>Abbrechen</button><button class="btn small primary" type="submit">Kontur übernehmen</button></div>
</form>{/if}
{#if importOpen}<OutlineImportDialog {documents} {planningProjectId} onapply={applyImport} onclose={()=>importOpen=false}/>{/if}
<style>.contour-editor{background:var(--paper);border:1px solid var(--line);padding:12px;font-size:10px;margin-top:12px}.contour-editor>p{line-height:1.7;color:var(--muted)}.contour-editor section{margin-top:12px}.contour-editor header{display:flex;justify-content:space-between;gap:7px;font-size:11px}.contour-editor label{display:block;font-size:10px;color:var(--muted);margin:9px 0}.contour-editor input,.contour-editor select{display:block;width:100%;font:inherit;font-size:12px;margin-top:5px;padding:8px;border:1px solid var(--line);border-radius:3px;background:var(--paper);min-height:36px;box-sizing:border-box}.edge{padding:11px 0;border-bottom:1px solid var(--line)}.edge>span{font-size:9px;color:var(--muted)}.pair{display:grid;grid-template-columns:1fr 1fr;gap:0 8px}.edge-actions,.actions{display:flex;gap:8px}.edge-actions button,.contour-editor header button{border:0;background:none;color:var(--forest);font-size:10px;cursor:pointer;padding:5px 0}.contour-editor .direction{display:flex;align-items:center;gap:7px}.direction input{width:15px;min-height:15px;margin:0}.contour-editor details{margin:15px 0}.contour-editor summary{cursor:pointer;font-size:10px;line-height:1.6}.error{white-space:pre-wrap;color:var(--danger);background:var(--danger-wash);padding:10px}.actions{margin-top:15px;flex-wrap:wrap}@media(max-width:720px){.contour-editor{font-size:12px}.contour-editor input,.contour-editor select{font-size:16px;min-height:48px}.contour-editor label{font-size:12px}.edge-actions button,.contour-editor header button{font-size:12px;min-height:44px}.edge>span{font-size:11px}.contour-editor summary{font-size:12px}}.contour-actions{display:flex;flex-wrap:wrap;gap:8px}.import-provenance{padding:14px;background:var(--wash);border:1px solid var(--line);margin-top:14px;font-size:12px;line-height:1.65}.import-provenance strong{font-size:13px}.import-provenance a{color:var(--forest)}.import-provenance details{margin:12px 0}.hash{font-family:monospace;overflow-wrap:anywhere}.contour-part+ .contour-part{border-top:2px solid var(--line);margin-top:20px;padding-top:16px}.contour-editor{font-size:12px}.contour-editor label{font-size:13px}.contour-editor header{font-size:13px}.contour-editor input,.contour-editor select,.contour-editor textarea{font-size:14px;min-height:44px}.contour-editor textarea{display:block;width:100%;box-sizing:border-box;margin-top:8px;border:1px solid var(--line);padding:10px;font:inherit}.edge>span,.contour-editor summary,.edge-actions button,.contour-editor header button{font-size:12px}.error{font-size:12px;line-height:1.6}.contour-editor .direction input{min-height:18px}@media(max-width:720px){.contour-editor input,.contour-editor select,.contour-editor textarea,.contour-actions .btn{font-size:16px;min-height:48px}} .quick-corners{margin-bottom:16px;padding:15px;background:var(--wash);border-radius:10px}.quick-corners summary{font-size:13px;font-weight:600;cursor:pointer;min-height:26px}.quick-corners p{font-size:12px;color:var(--muted);line-height:1.65}.quick-corners label{font-size:12px;display:block;margin:10px 0}.quick-corners input,.quick-corners select{width:100%;box-sizing:border-box;min-height:44px;display:block;margin-top:6px;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font:inherit}.quick-corners .btn{margin-top:8px}@media(max-width:720px){.quick-corners input,.quick-corners select{font-size:16px;min-height:48px}}.contour-editor{border-radius:10px;padding:16px}.edge{padding:16px 0}.contour-editor input,.contour-editor select{border-radius:8px}</style>
